def cleanup(self):
    for fname in os.listdir(self.root):
        if not fname.endswith(".json"):
            continue
        p = os.path.join(self.root, fname)
        try:
            with open(p) as f:
                rec = json.load(f)
            if rec["t"] + self.ttl < self._now():
                os.remove(p)
        except (IOError, json.JSONDecodeError):
            os.remove(p)
